static int fixed_gpio_emul_port_get_direction(const struct device *port, gpio_port_pins_t map,
					      gpio_port_pins_t *inputs, gpio_port_pins_t *outputs)
{
	gpio_port_pins_t ip = 0;
	gpio_port_pins_t op = 0;
	const struct gpio_driver_config *const cfg =
		(const struct gpio_driver_config *)port->config;

	map &= cfg->port_pin_mask;

	if (map != 0) {
		for (gpio_pin_t pin = 0; pin < GPIO_MAX_PINS_PER_PORT; pin++) {
			if ((map & BIT(pin)) != 0) {
				gpio_flags_t flags = 0;

				if (gpio_emul_flags_get(port, pin, &flags) == 0) {
					if ((flags & GPIO_INPUT) != 0) {
						ip |= BIT(pin);
					}
					if ((flags & GPIO_OUTPUT) != 0) {
						op |= BIT(pin);
					}
				}
			}
		}
	}

	if (inputs != NULL) {
		*inputs = ip;
	}

	if (outputs != NULL) {
		*outputs = op;
	}

	return 0;
}

